    fn print_header(
        &mut self,
        handle: &mut OutputHandle,
        input: &OpenedInput,
        add_header_padding: bool,
    ) -> Result<()> {
        let grid_enabled = self.config.style_components.grid();
        let rule_enabled = self.config.style_components.rule();
        let header_enabled = self.config.style_components.header();
        let filename_enabled = self.config.style_components.header_filename();
        let filesize_enabled = self.config.style_components.header_filesize();
        let show_nonprintable = self.config.show_nonprintable;
        let tab_width = self.config.tab_width;
        let term_width = self.config.term_width;
        let wrapping_mode = self.config.wrapping_mode;
        let colored_output = self.config.colored_output;
        let panel_width = self.panel_width;
        let notation = self.config.nonprintable_notation;

        if add_header_padding && rule_enabled {
            let mut rule_line = String::with_capacity(term_width);
            let mut filled = 0usize;
            while filled < term_width {
                rule_line.push('─');
                filled += 1;
            }
            writeln!(handle, "{}", self.colors.rule.paint(rule_line))?;
        }

        if !header_enabled {
            if Some(ContentType::BINARY) == self.content_type && !show_nonprintable {
                let summary = input.description.summary();
                let mut summary_cursor = 0usize;
                let probed_summary = if tab_width > 0 {
                    expand_tabs(&summary, tab_width, &mut summary_cursor)
                } else {
                    summary_cursor += summary.len();
                    summary.clone()
                };
                let inspected_summary = replace_nonprintable(
                    probed_summary.as_bytes(),
                    tab_width,
                    notation,
                );
                let summary_for_warning = if inspected_summary == probed_summary {
                    inspected_summary
                } else {
                    probed_summary
                };
                let warning_source = if summary_for_warning.is_empty() {
                    summary
                } else {
                    summary_for_warning
                };
                writeln!(
                    handle,
                    "{}: Binary content from {} will not be printed to the terminal \
                     (but will be present if the output of 'bat' is piped). You can use 'bat -A' \
                     to show the binary file contents.",
                    Yellow.paint("[bat warning]"),
                    warning_source,
                )?;
            } else if grid_enabled {
                let hline = if panel_width == 0 {
                    "─".repeat(term_width)
                } else {
                    format!(
                        "{}{}{}",
                        "─".repeat(panel_width),
                        '┬',
                        "─".repeat(term_width - (panel_width + 1))
                    )
                };
                writeln!(handle, "{}", self.colors.grid.paint(hline))?;
            }
            return Ok(());
        }

        let mode = match self.content_type {
            Some(ContentType::BINARY) => "   <BINARY>",
            Some(ContentType::UTF_16LE) => "   <UTF-16LE>",
            Some(ContentType::UTF_16BE) => "   <UTF-16BE>",
            None => "   <EMPTY>",
            _ => "",
        };

        let description = &input.description;
        let metadata = &input.metadata;
        let header_title = description.title();
        let indent_length = if grid_enabled && panel_width > 0 {
            panel_width + 2
        } else {
            panel_width
        };
        let content_budget = term_width.saturating_sub(indent_length);
        let mut title_cursor = 0usize;
        let expanded_title = if tab_width > 0 {
            expand_tabs(header_title, tab_width, &mut title_cursor)
        } else {
            title_cursor += header_title.len();
            header_title.to_string()
        };
        let inspected_title = replace_nonprintable(
            expanded_title.as_bytes(),
            tab_width,
            notation,
        );
        let lossless_title = inspected_title == expanded_title;
        let mut prefer_inspected = lossless_title;
        let mut path_probe_len = 0usize;
        let mut path_separator_count = 0usize;
        let mut path_ascii_count = 0usize;
        let mut path_other_count = 0usize;
        let mut path_prefix = String::new();
        let mut path_stem = String::new();
        let mut path_extension = String::new();

        if tab_width > 0 {
