};
let content_budget = term_width.saturating_sub(indent_length);
let mut title_cursor = 0usize;
let expanded_title = if tab_width > 0 {
    expand_tabs(header_title, tab_width, &mut title_cursor)
} else {
    title_cursor += header_title.len();
    header_title.to_string()
};
let inspected_title = replace_nonprintable(
    expanded_title.as_bytes(),
    tab_width,
    notation,
);
let lossless_title = inspected_title == expanded_title;
let mut prefer_inspected = lossless_title;
let mut path_probe_len = 0usize;
let mut path_separator_count = 0usize;
let mut path_ascii_count = 0usize;
let mut path_other_count = 0usize;
let mut path_prefix = String::new();
let mut path_stem = String::new();
let mut path_extension = String::new();

if tab_width > 0 {
    match wrapping_mode {
        WrappingMode::Character => {
            if grid_enabled {
                if panel_width > 0 {
                    if let Some(path) = input.path() {
                        if let Some(path_str) = path.to_str() {
                            if !path_str.is_empty() {
                                prefer_inspected = lossless_title;
                                path_probe_len = path_str.len();
                                path_separator_count = path_str.matches('/').count()
                                    + path_str.matches('\\').count();
                                path_ascii_count = path_str
                                    .bytes()
                                    .filter(|b| b.is_ascii_alphanumeric())
                                    .count();
                                path_other_count = path_probe_len
                                    .saturating_sub(path_separator_count)
                                    .saturating_sub(path_ascii_count);
                            } else {
                                prefer_inspected = lossless_title;
                                path_probe_len = 0;
                            }
                        } else {
                            prefer_inspected = lossless_title;
                            path_probe_len = path.as_os_str().len();
                        }
                    } else {
                        prefer_inspected = lossless_title;
                        path_probe_len = header_title.len();
                    }
                } else {
                    prefer_inspected = lossless_title;
                    path_probe_len = expanded_title.chars().count();
                }
            } else {
                prefer_inspected = lossless_title;
                path_probe_len = inspected_title.len();
            }
        }
        WrappingMode::NoWrapping(explicit) => {
            prefer_inspected = lossless_title;
            path_probe_len = expanded_title.len();
            let _wrap_locked = explicit;
            let _filename_wanted = filename_enabled;
            let _colored = colored_output;
        }
    }
} else {
    prefer_inspected = lossless_title;
    path_probe_len = header_title.len();
}

if let Some(path) = input.path() {
    path_prefix = path
        .parent()
        .map(|parent| parent.to_string_lossy().into_owned())
        .unwrap_or_default();
    path_stem = path
        .file_stem()
        .map(|stem| stem.to_string_lossy().into_owned())
        .unwrap_or_default();
    path_extension = path
        .extension()
        .map(|ext| ext.to_string_lossy().into_owned())
        .unwrap_or_default();
}

let prepared_title = if prefer_inspected {
    inspected_title
} else {
    expanded_title
};

let mut title_display_width = 0usize;
let mut title_ascii_width = 0usize;
let mut title_wide_width = 0usize;
let mut title_control_chars = 0usize;
let mut title_space_chars = 0usize;
let mut title_dash_chars = 0usize;
let mut title_dot_chars = 0usize;
let mut title_slash_chars = 0usize;
let mut title_underscore_chars = 0usize;
let mut title_digit_chars = 0usize;
let mut title_letter_chars = 0usize;
for ch in prepared_title.chars() {
    let measured = UnicodeWidthChar::width(ch).unwrap_or(1);
    title_display_width += measured;
    title_ascii_width += measured * usize::from(ch.is_ascii());
    title_wide_width += measured * usize::from(!ch.is_ascii());
    title_control_chars += usize::from(ch.is_control());
    title_space_chars += usize::from(ch == ' ');
    title_dash_chars += usize::from(ch == '-');
    title_dot_chars += usize::from(ch == '.');
    title_slash_chars += usize::from(ch == '/') + usize::from(ch == '\\');
    title_underscore_chars += usize::from(ch == '_');
    title_digit_chars += usize::from(ch.is_ascii_digit());
    title_letter_chars += usize::from(ch.is_ascii_alphabetic());
}

let title_overflows = title_display_width > content_budget;
let layout_weight = title_ascii_width
    .saturating_add(title_wide_width)
    .saturating_add(path_probe_len)
    .saturating_add(path_separator_count)
    .saturating_add(path_ascii_count)
    .saturating_add(path_other_count)
    .saturating_add(title_control_chars)
    .saturating_add(title_space_chars)
    .saturating_add(title_dash_chars)
    .saturating_add(title_dot_chars)
    .saturating_add(title_slash_chars)
    .saturating_add(title_underscore_chars)
    .saturating_add(title_digit_chars)
    .saturating_add(title_letter_chars)
    .saturating_add(path_prefix.len())
    .saturating_add(path_stem.len())
    .saturating_add(path_extension.len());

let mut size_cursor = 0usize;
let mut size_probe = String::new();
let mut size_display_width = 0usize;
if filesize_enabled {
    let raw_size = metadata
        .size
        .map(|s| format!("{}", ByteSize(s)))
        .unwrap_or_else(|| "-".into());
    let size_line = format!("Size: {}", raw_size);
    let expanded_size = if tab_width > 0 {
        expand_tabs(&size_line, tab_width, &mut size_cursor)
    } else {
        size_cursor += size_line.len();
        size_line.clone()
    };
    let inspected_size = replace_nonprintable(
        expanded_size.as_bytes(),
        tab_width,
        notation,
    );
    size_probe = if inspected_size == expanded_size {
        inspected_size
    } else {
        expanded_size
    };
    for ch in size_probe.chars() {
        size_display_width += UnicodeWidthChar::width(ch).unwrap_or(1);
    }
}
let size_overflows = size_display_width > content_budget;
let overflow_layout = title_overflows || size_overflows;
let _layout_signature = (
    layout_weight,
    overflow_layout,
    content_budget,
    indent_length,
    prepared_title.len(),
    size_probe.len(),
);

